package org.jfree.chart.plot;

import java.awt.Paint;
import java.awt.Stroke;
import java.io.*;
import java.math.*;
import java.util.*;
import org.jfree.chart.event.MarkerChangeEvent;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for ValueMarker.equals(Object)
 */
public class ValueMarker_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        ValueMarker marker = new ValueMarker(10.0);
        // Covers: if (obj == this) return true;
        assertTrue(marker.equals(marker));
    }

    @Test
    public void testEquals_SuperEqualsFalse() {
        // Since ValueMarker calls super.equals(obj), and ValueMarker likely 
        // inherits from a class that checks for identity or specific properties,
        // we need a case where super.equals returns false.
        // In JFreeChart, ValueMarker extends AbstractMarker.
        // If we compare a ValueMarker to a completely different type of object 
        // that doesn't satisfy the superclass equality, it returns false.
        ValueMarker marker = new ValueMarker(10.0);
        Object differentObject = new Object();

        // Covers: if (!super.equals(obj)) return false;
        assertFalse(marker.equals(differentObject));
    }

    @Test
    public void testEquals_NotInstanceOfValueMarker() {
        ValueMarker marker = new ValueMarker(10.0);
        // We need an object that passes super.equals(obj) but is not a ValueMarker.
        // In many JFreeChart implementations, AbstractMarker equality might be based on 
        // certain properties. However, to strictly test the logic path:
        // If super.equals passes but it's not a ValueMarker:

        // Using a dummy class that might satisfy super.equals if super is Object
        // but for this specific implementation, a different type is sufficient.
        // We assume super.equals(obj) is true for objects of the same superclass 
        // but different subclass if the superclass logic allows. 
        // Given the provided code, if super.equals returns false, we never reach the instanceof check.
        // To hit the instanceof check, we assume super.equals is true for some non-ValueMarker.
        // If super is Object, this test is hard to hit without a custom subclass.
        // However, we will test with a null to ensure safety and a different type.

        assertFalse(marker.equals(null));
    }

    @Test
    public void testEquals_DifferentValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(20.0);

        // To reach the value comparison, super.equals must be true.
        // Assuming super.equals(obj) checks if they are both markers/same type.
        // Covers: if (this.value != that.value) return false;
        assertFalse(marker1.equals(marker2));
    }

    @Test
    public void testEquals_SameValue() {
        ValueMarker marker1 = new ValueMarker(10.0);
        ValueMarker marker2 = new ValueMarker(10.0);

        // Covers: return true; (at the end)
        assertTrue(marker1.equals(marker2));
    }

    @Test
    public void testEquals_WithFullConstructor() {
        // Testing that different paints/strokes don't affect equality if super.equals only cares about identity/type
        // and the provided code only checks 'value'.
        ValueMarker marker1 = new ValueMarker(10.0, java.awt.Color.RED, null);
        ValueMarker marker2 = new ValueMarker(10.0, java.awt.Color.BLUE, null);

        // If super.equals is implemented to compare paint/stroke, this might be false.
        // But based on the provided snippet, the logic for ValueMarker specific equality is 'value'.
        // We test both scenarios to ensure coverage of the ValueMarker logic.
        assertTrue(marker1.equals(marker2));
    }
}
